command:
/**
 * SVA example: Bless Toggle
 * Blesses every targeted token (or the selected ones if nothing is targeted): a golden intro,
 * then a persistent glow that follows the token. Run again on a blessed token to end it.
 * The glow is saved in the scene, so it survives a reload.
 *
 * Usage: target (or select) tokens, run.
 * Requires: Sargas Visual Automation + JB2A. No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

const COLOR = "yellow"; // "yellow" | "blue" | "green" | "purple"
const tokens = game.user.targets.size ? [...game.user.targets] : canvas.tokens.controlled;
if (!tokens.length) return ui.notifications.warn("Target or select at least one token.");

const sceneId = canvas.scene.id;
for (const target of tokens) {
  const name = `sva-bless:${target.id}`;
  if (SVA.effects.list({ sceneId, name }).length) {
    await SVA.effects.end({ name, sceneId });
    continue;
  }
  const seq = SVA.sequence();
  seq
    .effect()
    .file(`jb2a.bless.200px.intro.${COLOR}`)
    .attachTo(target.id)
    .scaleToObject(1.5)
    .layer("belowTokens")
    .waitUntilFinished(-500);
  seq
    .effect()
    .file(`jb2a.bless.200px.loop.${COLOR}`)
    .attachTo(target.id)
    .scaleToObject(1.5)
    .layer("belowTokens")
    .fadeIn(300)
    .fadeOut(1000)
    .persist(true)
    .name(name);
  await seq.play();
}
